public enum CCSwitchVariant: String, CaseIterable, Sendable {
    case primary
    case success
    case error
    case warning
    case info
}

public enum CCSwitchSize: String, CaseIterable, Sendable {
    case large
    case medium
    case small
}

public enum CCSwitchChecked: String, CaseIterable, Sendable {
    case `true`
    case `false`
}

public struct CCSwitchStyle: Equatable, Sendable {
    public var thumbColor: SwiftUI.Color?
    public var switchBgColor: SwiftUI.Color?
    public var borderColor: SwiftUI.Color?
    public var checkedBgColor: SwiftUI.Color?
    public var width: CGFloat?
    public var height: CGFloat?
    public var thumbSize: CGFloat?
    public var thumbOffset: CGFloat?
    public var thumbBorderColor: SwiftUI.Color?

    /// Base, then each variant dimension, then compound
    /// variants — the order the CSS cascade encodes.
    public static func resolve(
        variant: CCSwitchVariant,
        size: CCSwitchSize,
        checked: CCSwitchChecked,
        scheme: ColorScheme,
        brand: CocsoBrand = .base
    ) -> CCSwitchStyle {
        var style = CCSwitchStyle()
        style.thumbColor = CocsoTokens.Color.textOnPrimary(scheme, brand: brand)
        style.switchBgColor = CocsoTokens.Color.surfaceNeutral(scheme, brand: brand)
        style.borderColor = CocsoTokens.Color.borderStrong(scheme, brand: brand)
        if variant == .primary {
            style.checkedBgColor = CocsoTokens.Color.interactivePrimary(scheme, brand: brand)
        }
        if variant == .success {
            style.checkedBgColor = CocsoTokens.Color.interactiveSuccess(scheme, brand: brand)
        }
        if variant == .error {
            style.checkedBgColor = CocsoTokens.Color.interactiveDanger(scheme, brand: brand)
        }
        if variant == .warning {
            style.checkedBgColor = CocsoTokens.Color.interactiveWarningActive(scheme, brand: brand)
        }
        if variant == .info {
            style.checkedBgColor = CocsoTokens.Color.interactiveInfo(scheme, brand: brand)
        }
        if size == .large {
            style.width = 40
            style.height = 22
            style.thumbSize = 18
            style.thumbOffset = 2
        }
        if size == .medium {
            style.width = 36
            style.height = 20
            style.thumbSize = 16
            style.thumbOffset = 2
        }
        if size == .small {
            style.width = 32
            style.height = 18
            style.thumbSize = 14
            style.thumbOffset = 2
        }
        if checked == .`false` {
            style.thumbBorderColor = CocsoTokens.Color.textSecondary(scheme, brand: brand)
        }
        if variant == .primary && checked == .`true` {
            style.switchBgColor = CocsoTokens.Color.interactivePrimary(scheme, brand: brand)
        }
        if variant == .success && checked == .`true` {
            style.switchBgColor = CocsoTokens.Color.interactiveSuccess(scheme, brand: brand)
        }
        if variant == .error && checked == .`true` {
            style.switchBgColor = CocsoTokens.Color.interactiveDanger(scheme, brand: brand)
        }
        if variant == .warning && checked == .`true` {
            style.switchBgColor = CocsoTokens.Color.interactiveWarningActive(scheme, brand: brand)
        }
        if variant == .info && checked == .`true` {
            style.switchBgColor = CocsoTokens.Color.interactiveInfo(scheme, brand: brand)
        }
        return style
    }
}

public enum CCTypographyType: String, CaseIterable, Sendable {
    case body
    case heading
}

public enum CCTypographySize: String, CaseIterable, Sendable {
    case xLarge
    case large
    case medium
    case small
    case xSmall
}

public struct CCTypographyStyle: Equatable, Sendable {
    public var fontWeight: Font.Weight?
    public var fontSize: CGFloat?

    /// Base, then each variant dimension, then compound
    /// variants — the order the CSS cascade encodes.
    public static func resolve(
        type: CCTypographyType,
        size: CCTypographySize,
        scheme: ColorScheme,
        brand: CocsoBrand = .base
    ) -> CCTypographyStyle {
        var style = CCTypographyStyle()
        if type == .heading {
            style.fontWeight = .bold
        }
        if size == .xLarge {
            style.fontSize = 28
        }
        if size == .large {
            style.fontSize = 24
        }
        if size == .medium {
            style.fontSize = 20
        }
        if size == .small {
            style.fontSize = 16
        }
        if size == .xSmall {
            style.fontSize = 14
        }
        if type == .body && size == .xLarge {
            style.fontSize = 18
        }
        if type == .body && size == .large {
            style.fontSize = 18
        }
        if type == .body && size == .medium {
            style.fontSize = 16
        }
        if type == .body && size == .small {
            style.fontSize = 14
        }
        if type == .body && size == .xSmall {
            style.fontSize = 12
        }
        return style
    }
}
